<template>
  <div class="home-recharge">
    <!-- <title-line :title="title" /> -->
    <div class="upgradeImg" />
  </div>
</template>
<script>
// import TitleLine from './modules/TitleLine'
import { getUInfoByToken } from '@/api/user'
export default {
  components: {
    // TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: '升级中',
      interval: null
    }
  },
  async mounted() {
    if (this.interval) {
      clearInterval(this.interval)
    }
    this.interval = setInterval(async() => {
      const res = await getUInfoByToken()
      if (res.status !== '8888') {
        clearInterval(this.interval)
        if (localStorage.getItem('version') === 'new') {
          this.$router.push({ path: '/home' })
        } else {
          this.$router.push({ path: '/oldhome' })
        }
      }
    }, 10 * 1000)
  },
  beforeDestroy() {
    if (this.interval) {
      clearInterval(this.interval)
    }
  },
  methods: {
  }

}
</script>
<style lang="less">
.home-recharge {
    min-height: 100vh;
    width: 100%;
    background: #19223b;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .upgradeImg{
      width:100% ;
      height: 1334px;
      background-image: url(~@/assets/portal/upgrade.png);
      background-position: 0% 0%;
      background-size: 100% 100%;
      background-repeat: no-repeat;
    }
}
</style>
